import { useQuery } from "@tanstack/react-query";
import { formatCurrency } from "@/lib/formatters";
import { Laptop, Smartphone, Mouse, Keyboard, Package } from "lucide-react";
import type { Product, SaleItem } from "@shared/schema";

const productIcons: Record<string, React.ComponentType<any>> = {
  laptop: Laptop,
  smartphone: Smartphone,
  mouse: Mouse,
  keyboard: Keyboard,
  default: Package,
};

function getProductIcon(productName: string) {
  const name = productName.toLowerCase();
  if (name.includes('notebook') || name.includes('laptop')) return productIcons.laptop;
  if (name.includes('iphone') || name.includes('smartphone') || name.includes('celular')) return productIcons.smartphone;
  if (name.includes('mouse')) return productIcons.mouse;
  if (name.includes('teclado') || name.includes('keyboard')) return productIcons.keyboard;
  return productIcons.default;
}

export default function TopProducts() {
  const { data: products } = useQuery({
    queryKey: ["/api/products"],
  });

  const { data: sales } = useQuery({
    queryKey: ["/api/sales"],
  });

  const { data: saleItems } = useQuery({
    queryKey: ["/api/sales", "items"],
    queryFn: async () => {
      if (!sales) return [];

      const allItems: any[] = [];
      for (const sale of sales) {
        const response = await fetch(`/api/sales/${sale.id}/items`);
        if (response.ok) {
          const items = await response.json();
          allItems.push(...items);
        }
      }
      return allItems;
    },
    enabled: !!sales,
  });

  if (!products || !saleItems) {
    return (
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-6">Produtos Mais Vendidos</h3>
        <div className="space-y-4 animate-pulse">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-gray-200 rounded-lg"></div>
                <div>
                  <div className="h-4 bg-gray-200 rounded w-32 mb-1"></div>
                  <div className="h-3 bg-gray-200 rounded w-16"></div>
                </div>
              </div>
              <div className="text-right">
                <div className="h-4 bg-gray-200 rounded w-20 mb-1"></div>
                <div className="w-16 h-2 bg-gray-200 rounded-full"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // Calculate product sales statistics
  const productStats = new Map();

  saleItems.forEach((item: SaleItem) => {
    const existing = productStats.get(item.productId) || { quantity: 0, revenue: 0 };
    productStats.set(item.productId, {
      quantity: existing.quantity + item.quantity,
      revenue: existing.revenue + parseFloat(item.total)
    });
  });

  // Get top products by revenue
  const topProducts = Array.from(productStats.entries())
    .map(([productId, stats]) => {
      const product = products.find((p: Product) => p.id === productId);
      return product ? { ...product, stats } : null;
    })
    .filter(Boolean)
    .sort((a: any, b: any) => b.stats.revenue - a.stats.revenue)
    .slice(0, 4);

  const maxRevenue = topProducts[0]?.stats.revenue || 1;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-gray-900">Produtos Mais Vendidos</h3>
        <button className="text-blue-600 hover:text-blue-700 text-sm font-medium">
          Ver todos
        </button>
      </div>

      {topProducts.length === 0 ? (
        <div className="text-center text-gray-500 py-8">
          <p>Nenhuma venda registrada ainda</p>
        </div>
      ) : (
        <div className="space-y-4">
          {topProducts.map((product: any) => {
            const IconComponent = getProductIcon(product.name);
            const progressWidth = (product.stats.revenue / maxRevenue) * 100;

            return (
              <div key={product.id} className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gray-200 rounded-lg flex items-center justify-center">
                    <IconComponent className="text-gray-500 h-5 w-5" />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">{product.name}</p>
                    <p className="text-xs text-gray-500">
                      {product.stats.quantity} venda{product.stats.quantity > 1 ? 's' : ''}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-medium text-gray-900">
                    {formatCurrency(product.stats.revenue)}
                  </p>
                  <div className="w-16 h-2 bg-gray-200 rounded-full">
                    <div 
                      className="h-2 bg-blue-500 rounded-full"
                      style={{ width: `${progressWidth}%` }}
                    />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

client/src/components/forms/customer-for.content:
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation } from "@tanstack/react-query";
import { z } from "zod";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Search, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { queryClient } from "@/lib/queryClient";
import { insertCustomerSchema } from "@shared/schema";
import { documentValidationSchema, validateCPF, validateCNPJ } from "@/lib/validators";
import { getDocumentType } from "@/lib/formatters";
import type { Customer } from "@shared/schema";

const customerFormSchema = insertCustomerSchema.extend({
  document: documentValidationSchema,
  email: z.string().email("E-mail inválido").optional().or(z.literal("")),
});

interface CustomerFormProps {
  customer?: Customer;
  onSuccess?: () => void;
}

export default function CustomerForm({ customer, onSuccess }: CustomerFormProps) {
  const { toast } = useToast();
  const [isSearchingCNPJ, setIsSearchingCNPJ] = useState(false);

  const form = useForm<z.infer<typeof customerFormSchema>>({
    resolver: zodResolver(customerFormSchema),
    defaultValues: {
      name: customer?.name || "",
      document: customer?.document || "",
      documentType: customer?.documentType || "CPF",
      email: customer?.email || "",
      phone: customer?.phone || "",
      address: customer?.address || "",
      city: customer?.city || "",
      state: customer?.state || "",
      zipCode: customer?.zipCode || "",
      isActive: customer?.isActive ?? true,
      classification: customer?.classification || "REGULAR",
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: z.infer<typeof customerFormSchema>) => {
      const response = await fetch("/api/customers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error("Failed to create customer");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/customers"] });
      toast({
        title: "Cliente cadastrado",
        description: "Cliente foi cadastrado com sucesso.",
      });
      onSuccess?.();
    },
    onError: (error: any) => {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async (data: z.infer<typeof customerFormSchema>) => {
      const response = await fetch(`/api/customers/${customer!.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error("Failed to update customer");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/customers"] });
      toast({
        title: "Cliente atualizado",
        description: "Cliente foi atualizado com sucesso.",
      });
      onSuccess?.();
    },
    onError: (error: any) => {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: z.infer<typeof customerFormSchema>) => {
    // Auto-detect document type
    const documentType = getDocumentType(data.document);
    const submitData = { ...data, documentType };

    if (customer) {
      updateMutation.mutate(submitData);
    } else {
      createMutation.mutate(submitData);
    }
  };

  const searchCNPJMutation = useMutation({
    mutationFn: async (cnpj: string) => {
      // Remove formatting from CNPJ
      const cleanCNPJ = cnpj.replace(/[^\d]/g, '');

      // Use a free Brazilian CNPJ API
      const response = await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cleanCNPJ}`);
      if (!response.ok) {
        throw new Error("CNPJ não encontrado ou API temporariamente indisponível");
      }
      return response.json();
    },
    onSuccess: (data) => {
      // Fill form with API data
      const companyName = data.razao_social || data.nome_fantasia || "";
      form.setValue("name", companyName);

      // Contact information
      if (data.email) {
        form.setValue("email", data.email);
      }

      // Phone formatting
      if (data.ddd_telefone_1 && data.telefone_1) {
        const formattedPhone = `(${data.ddd_telefone_1}) ${data.telefone_1.replace(/(\d{4,5})(\d{4})/, '$1-$2')}`;
        form.setValue("phone", formattedPhone);
      }

      // Address information
      let fullAddress = "";
      if (data.logradouro) {
        fullAddress = data.logradouro;
        if (data.numero) {
          fullAddress += `, ${data.numero}`;
        }
        if (data.complemento) {
          fullAddress += `, ${data.complemento}`;
        }
        if (data.bairro) {
          fullAddress += ` - ${data.bairro}`;
        }
        form.setValue("address", fullAddress);
      }

      form.setValue("city", data.municipio || "");
      form.setValue("state", data.uf || "");
      form.setValue("zipCode", data.cep || "");

      toast({
        title: "Dados importados com sucesso!",
        description: `Informações da empresa ${companyName} foram preenchidas automaticamente.`,
      });
    },
    onError: (error: any) => {
      toast({
        title: "Erro na consulta",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleSearchCNPJ = () => {
    const document = form.getValues("document");
    if (!document) {
      toast({
        title: "CNPJ obrigatório",
        description: "Digite um CNPJ para realizar a busca.",
        variant: "destructive",
      });
      return;
    }

    const cleanCNPJ = document.replace(/[^\d]/g, '');
    if (cleanCNPJ.length !== 14) {
      toast({
        title: "CNPJ inválido",
        description: "O CNPJ deve ter 14 dígitos.",
        variant: "destructive",
      });
      return;
    }

    if (!validateCNPJ(cleanCNPJ)) {
      toast({
        title: "CNPJ inválido",
        description: "O CNPJ digitado não é válido.",
        variant: "destructive",
      });
      return;
    }

    searchCNPJMutation.mutate(document);
  };

  const isPending = createMutation.isPending || updateMutation.isPending;
  const documentValue = form.watch("document");
  const detectedType = documentValue ? getDocumentType(documentValue) : null;
  const canSearchCNPJ = detectedType === "CNPJ" && !customer; // Only for new customers

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div className="col-span-2">
          <Label htmlFor="name">Nome/Razão Social *</Label>
          <Input
            id="name"
            {...form.register("name")}
            placeholder="Digite o nome completo"
          />
          {form.formState.errors.name && (
            <p className="text-sm text-red-600 mt-1">{form.formState.errors.name.message}</p>
          )}
        </div>

        <div className="col-span-2">
          <Label htmlFor="document">CPF/CNPJ *</Label>
          <div className="flex gap-2">
            <Input
              id="document"
              {...form.register("document")}
              placeholder="000.000.000-00 ou 00.000.000/0000-00"
              className="flex-1"
            />
            {canSearchCNPJ && (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleSearchCNPJ}
                disabled={searchCNPJMutation.isPending}
                className="px-3"
              >
                {searchCNPJMutation.isPending ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Search className="h-4 w-4" />
                )}
              </Button>
            )}
          </div>
          {detectedType && (
            <p className="text-xs text-gray-500 mt-1">
              Tipo detectado: {detectedType}
              {canSearchCNPJ && (
                <span className="text-blue-600 ml-2">• Clique no ícone para buscar dados da empresa</span>
              )}
            </p>
          )}
          {form.formState.errors.document && (
            <p className="text-sm text-red-600 mt-1">{form.formState.errors.document.message}</p>
          )}
        </div>

        <div>
          <Label htmlFor="email">E-mail</Label>
          <Input
            id="email"
            type="email"
            {...form.register("email")}
            placeholder="cliente@exemplo.com"
          />
          {form.formState.errors.email && (
            <p className="text-sm text-red-600 mt-1">{form.formState.errors.email.message}</p>
          )}
        </div>

        <div>
          <Label htmlFor="phone">Telefone</Label>
          <Input
            id="phone"
            {...form.register("phone")}
            placeholder="(11) 99999-9999"
          />
        </div>

        <div className="col-span-2">
          <Label htmlFor="address">Endereço</Label>
          <Input
            id="address"
            {...form.register("address")}
            placeholder="Rua, número, complemento"
          />
        </div>

        <div>
          <Label htmlFor="city">Cidade</Label>
          <Input
            id="city"
            {...form.register("city")}
            placeholder="São Paulo"
          />
        </div>

        <div>
          <Label htmlFor="state">Estado</Label>
          <Input
            id="state"
            {...form.register("state")}
            placeholder="SP"
            maxLength={2}
          />
        </div>

        <div>
          <Label htmlFor="zipCode">CEP</Label>
          <Input
            id="zipCode"
            {...form.register("zipCode")}
            placeholder="00000-000"
          />
        </div>

        <div>
          <Label htmlFor="classification">Classificação</Label>
          <Select
            value={form.watch("classification")}
            onValueChange={(value) => form.setValue("classification", value)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="REGULAR">Regular</SelectItem>
              <SelectItem value="VIP">VIP</SelectItem>
              <SelectItem value="INACTIVE">Inativo</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="col-span-2 flex items-center space-x-2">
          <Switch
            id="isActive"
            checked={form.watch("isActive")}
            onCheckedChange={(checked) => form.setValue("isActive", checked)}
          />
          <Label htmlFor="isActive">Cliente ativo</Label>
        </div>
      </div>

      <div className="flex justify-end space-x-2 pt-4">
        <Button type="button" variant="outline" onClick={onSuccess}>
          Cancelar
        </Button>
        <Button type="submit" disabled={isPending}>
          {isPending ? "Salvando..." : customer ? "Atualizar" : "Cadastrar"}
        </Button>
      </div>
    </form>
  );
}

client/src/components/forms/product-form.content:
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery } from "@tanstack/react-query";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { queryClient } from "@/lib/queryClient";
import { insertProductSchema } from "@shared/schema";
import type { Product, Category, Supplier } from "@shared/schema";

const productFormSchema = insertProductSchema.extend({
  costPrice: z.string().min(1, "Preço de custo é obrigatório"),
  salePrice: z.string().min(1, "Preço de venda é obrigatório"),
  currentStock: z.string().optional(),
  minimumStock: z.string().optional(),
  maximumStock: z.string().optional(),
});

interface ProductFormProps {
  product?: Product;
  onSuccess?: () => void;
}

export default function ProductForm({ product, onSuccess }: ProductFormProps) {
  const { toast } = useToast();

  const { data: categories } = useQuery({
    queryKey: ["/api/categories"],
  });

  const { data: suppliers } = useQuery({
    queryKey: ["/api/suppliers"],
  });

  const form = useForm<z.infer<typeof productFormSchema>>({
    resolver: zodResolver(productFormSchema),
    defaultValues: {
      code: product?.code || "",
      barcode: product?.barcode || "",
      name: product?.name || "",
      description: product?.description || "",
      categoryId: product?.categoryId || "",
      supplierId: product?.supplierId || "",
      unit: product?.unit || "UN",
      costPrice: product?.costPrice || "",
      salePrice: product?.salePrice || "",
      currentStock: product?.currentStock?.toString() || "0",
      minimumStock: product?.minimumStock?.toString() || "0",
      maximumStock: product?.maximumStock?.toString() || "1000",
      isActive: product?.isActive ?? true,
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: z.infer<typeof productFormSchema>) => {
      const submitData = {
        ...data,
        costPrice: data.costPrice,
        salePrice: data.salePrice,
        currentStock: data.currentStock ? parseInt(data.currentStock) : 0,
        minimumStock: data.minimumStock ? parseInt(data.minimumStock) : 0,
        maximumStock: data.maximumStock ? parseInt(data.maximumStock) : 1000,
        categoryId: data.categoryId || null,
        supplierId: data.supplierId || null,
      };

      const response = await fetch("/api/products", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(submitData),
      });
      if (!response.ok) throw new Error("Failed to create product");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/products"] });
      toast({
        title: "Produto cadastrado",
        description: "Produto foi cadastrado com sucesso.",
      });
      onSuccess?.();
    },
    onError: (error: any) => {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async (data: z.infer<typeof productFormSchema>) => {
      const submitData = {
        ...data,
        costPrice: data.costPrice,
        salePrice: data.salePrice,
        currentStock: data.currentStock ? parseInt(data.currentStock) : 0,
        minimumStock: data.minimumStock ? parseInt(data.minimumStock) : 0,
        maximumStock: data.maximumStock ? parseInt(data.maximumStock) : 1000,
        categoryId: data.categoryId || null,
        supplierId: data.supplierId || null,
      };

      const response = await fetch(`/api/products/${product!.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(submitData),
      });
      if (!response.ok) throw new Error("Failed to update product");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/products"] });
      toast({
        title: "Produto atualizado",
        description: "Produto foi atualizado com sucesso.",
      });
      onSuccess?.();
    },
    onError: (error: any) => {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: z.infer<typeof productFormSchema>) => {
    if (product) {
      updateMutation.mutate(data);
    } else {
      createMutation.mutate(data);
    }
  };

  const isPending = createMutation.isPending || updateMutation.isPending;

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4 max-h-[60vh] overflow-y-auto">
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="code">Código *</Label>
          <Input
            id="code"
            {...form.register("code")}
            placeholder="Digite o código do produto"
          />
          {form.formState.errors.code && (
            <p className="text-sm text-red-600 mt-1">{form.formState.errors.code.message}</p>
          )}
        </div>

        <div>
          <Label htmlFor="barcode">Código de Barras</Label>
          <Input
            id="barcode"
            {...form.register("barcode")}
            placeholder="Digite o código de barras"
          />
        </div>

        <div className="col-span-2">
          <Label htmlFor="name">Nome *</Label>
          <Input
            id="name"
            {...form.register("name")}
            placeholder="Digite o nome do produto"
          />
          {form.formState.errors.name && (
            <p className="text-sm text-red-600 mt-1">{form.formState.errors.name.message}</p>
          )}
        </div>

        <div className="col-span-2">
          <Label htmlFor="description">Descrição</Label>
          <Textarea
            id="description"
            {...form.register("description")}
            placeholder="Digite uma descrição para o produto"
            rows={3}
          />
        </div>

        <div>
          <Label htmlFor="categoryId">Categoria</Label>
          <Select
            value={form.watch("categoryId")}
            onValueChange={(value) => form.setValue("categoryId", value)}
          >
            <SelectTrigger>
