  { name: "Importar NF", href: "/import", icon: FileInput },
];

function NavLink({ href, icon: Icon, children, isActive }: {
  href: string;
  icon: React.ComponentType<any>;
  children: React.ReactNode;
  isActive: boolean;
}) {
  return (
    <Link href={href}>
