      <div className="mt-2 space-y-1">
        {items.map((item) => (
          <NavLink
            key={item.name}
            href={item.href}
            icon={item.icon}
            isActive={location === item.href}
          >
            {item.name}
          </NavLink>
        ))}
      </div>
    </div>
  );
}

export default function Sidebar() {
